"""Dependency-free Ingress UI using the ACP/AEP visual language."""

ADMIN_CSS = r"""
:root{color-scheme:light;scrollbar-gutter:stable;--bg:#f3f6f9;--surface:#fff;--surface2:#edf3f7;--text:#17243a;--muted:#687b90;--line:#d8e2eb;--cyan:#058caf;--cyan-soft:#dff5fa;--good:#16845b;--danger:#c43f55;--shadow:0 5px 22px #1e3a5f12}html[data-theme=dark]{color-scheme:dark;--bg:#0d1420;--surface:#172235;--surface2:#202c41;--text:#e7edf5;--muted:#a4b2c6;--line:#30415d;--cyan:#52c9e6;--cyan-soft:#173b4a;--good:#50c895;--danger:#ff8798;--shadow:none}*{box-sizing:border-box}[hidden]{display:none!important}body{font:15px system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;background:var(--bg);color:var(--text);margin:0}body.drawer-open{overflow:hidden}.app{max-width:1840px;margin:auto;padding:22px clamp(18px,2.8vw,48px) 40px}.site-header{margin-bottom:28px}.header-main{display:flex;align-items:center;gap:20px;min-height:58px}.brand{display:flex;align-items:center;gap:11px;color:var(--cyan);text-decoration:none;font-size:24px;font-weight:800;letter-spacing:-.02em}.brand img{width:46px;height:46px;object-fit:contain;filter:drop-shadow(0 4px 8px #102a4330)}.brand b{font-size:13px;color:var(--muted);font-weight:650;white-space:nowrap}.header-actions{display:flex;gap:8px;margin-left:auto}.switch,.secondary,.danger{color:var(--text);padding:9px 12px;border-radius:7px;border:1px solid var(--line);background:var(--surface);font:inherit;cursor:pointer}.danger{color:var(--danger);border-color:color-mix(in srgb,var(--danger) 40%,transparent)}button:disabled{opacity:.45;cursor:not-allowed}.nav-scroll{margin-top:12px;overflow-x:auto}.nav{display:flex;gap:5px;width:max-content;min-width:100%}.nav a{color:var(--text);text-decoration:none;padding:9px 12px;border-radius:7px}.nav a.active{background:var(--cyan-soft);color:var(--cyan);font-weight:700}.view{display:none}.view.active{display:block}.pagehead{display:flex;justify-content:space-between;align-items:center;gap:16px;margin:4px 0 20px}.pagehead h1{font-size:29px;margin:0 0 5px;letter-spacing:-.025em}.pagehead p,.card p{margin:0;color:var(--muted);line-height:1.55}.primary{color:#fff;background:var(--cyan);padding:10px 14px;border-radius:7px;border:0;font:inherit;font-weight:700;white-space:nowrap;cursor:pointer}.metrics{display:grid;grid-template-columns:repeat(3,minmax(150px,1fr));gap:12px}.card,.metric,.item-card{background:var(--surface);border:1px solid var(--line);border-radius:12px;padding:18px;box-shadow:var(--shadow)}.metric{position:relative;overflow:hidden}.metric:before{content:"";position:absolute;left:0;top:0;bottom:0;width:3px;background:var(--cyan)}.metric strong{display:block;font-size:25px;line-height:1.2}.metric span{display:block;color:var(--muted);margin-top:5px}.notice{margin-top:16px}.notice h2,.item-card h2{font-size:19px;margin:0 0 7px}.state{display:inline-flex;align-items:center;gap:8px;color:var(--good);font-weight:700}.state:before{content:"";width:9px;height:9px;border-radius:50%;background:currentColor}.state.revoked,.state.archived{color:var(--danger)}.card-list{display:grid;gap:12px}.item-card{display:flex;align-items:center;justify-content:space-between;gap:20px}.item-card .meta{color:var(--muted);font:12px ui-monospace,SFMono-Regular,Consolas,monospace}.actions{display:flex;gap:7px;flex-wrap:wrap}.filter{display:block;margin:-8px 0 16px;color:var(--muted)}.empty{text-align:center;color:var(--muted);padding:32px}.drawer-shell{position:fixed;inset:0;z-index:1000}.drawer-overlay{position:absolute;inset:0;background:#07132180;backdrop-filter:blur(2px)}.drawer{position:absolute;inset:0 0 0 auto;width:min(520px,calc(100vw - 36px));background:var(--surface);border-left:1px solid var(--line);box-shadow:-18px 0 45px #07132135;display:flex;flex-direction:column;outline:0}.drawer-head{display:flex;align-items:flex-start;justify-content:space-between;gap:18px;padding:22px 24px;border-bottom:1px solid var(--line)}.drawer-head h2{margin:0;font-size:22px}.drawer-close{font-size:22px;line-height:1;padding:8px 11px}.drawer-body{padding:24px;overflow:auto}.drawer-body dl{display:grid;grid-template-columns:auto 1fr;gap:10px 16px}.drawer-body dt{font-weight:700}.drawer-body dd{margin:0;color:var(--muted)}.form-grid{display:grid;gap:15px}.form-grid label{font-weight:650}.form-grid input{display:block;width:100%;margin-top:6px;padding:10px;color:var(--text);background:var(--surface);border:1px solid var(--line);border-radius:7px}.warning{padding:12px;background:#fff5df;color:#76520f;border-radius:7px}.message{color:var(--danger);min-height:1.2em}.credential{white-space:pre-wrap;overflow-wrap:anywhere;background:var(--surface2);border:1px solid var(--line);border-radius:8px;padding:14px;user-select:all}
@media(max-width:850px){.app{padding:16px}.nav-scroll{margin-inline:-16px;padding-inline:16px}.metrics{grid-template-columns:1fr}.pagehead{align-items:flex-start;flex-direction:column}.item-card{align-items:flex-start;flex-direction:column}}@media(max-width:560px){.brand{font-size:19px}.brand img{width:40px;height:40px}.header-main{align-items:flex-start}.header-actions{flex-direction:column}.pagehead h1{font-size:25px}.drawer{width:100vw}.drawer-body dl{grid-template-columns:1fr;gap:4px}.drawer-body dd{margin-bottom:8px}}
"""

ADMIN_JS = r"""
const app=document.querySelector('.app'),base=app.dataset.base;let language=localStorage.getItem('mcb-language')||((navigator.language||'fr').toLowerCase().startsWith('fr')?'fr':'en'),theme=localStorage.getItem('mcb-theme')||(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'),namespaces=[];
const I={fr:{overview:'Vue d’ensemble',clients:'Clients MCP',targets:'Cibles',access:'Accès MCP',ssh:'Capacités SSH',web:'Cibles Web',sessions:'Sessions',overviewTitle:'Vue d’ensemble',overviewIntro:'État réel du serveur MCP multi-client.',statusAction:'Voir le statut',appState:'Application',publicSurface:'Surface publique',ready:'Prête',authenticatedMcp:'MCP authentifié',coreTitle:'Socle MCP opérationnel',coreText:'Chaque client possède son namespace et son credential. Aucun adaptateur SSH ou Web n’est encore installé.',clientsIntro:'Gérez les clients MCP isolés et leurs credentials.',targetsIntro:'Les cibles apparaîtront avec les adaptateurs des lots suivants.',accessIntro:'Publications explicites des capacités vers les namespaces.',createClient:'Créer un client MCP',showArchived:'Afficher les clients archivés',technicalKey:'Clé technique',displayName:'Nom affiché',credentialWarning:'Le credential donnera accès aux outils publiés dans ce namespace.',credentialOnce:'Copiez ce secret maintenant. Il ne pourra plus être affiché.',copied:'J’ai copié le secret',create:'Créer',cancel:'Annuler',rotate:'Renouveler',revoke:'Révoquer',archive:'Archiver',active:'Actif',revoked:'Révoqué',archived:'Archivé',emptyClients:'Aucun client MCP.',emptyTargets:'Aucune cible : aucun adaptateur installé.',emptyAccess:'Aucune capacité publiée.',runtime:'Runtime',listeners:'Listeners',scope:'Périmètre',singleRuntime:'Processus unique',listenerValuesMcp:'8099 Ingress · 8098 MCP',scopeValue1:'Lot 1 — cœur MCP',close:'Fermer',plannedTitle:'Fonction prévue dans un lot ultérieur',plannedText:'Cette vue reste vide jusqu’à l’installation de son adaptateur.',createTitle:'Créer un client MCP',credentialTitle:'Credential à copier',confirmRevoke:'Révoquer définitivement ce client ?',confirmArchive:'Archiver ce client révoqué ?',namespace_key_exists:'Cette clé existe déjà.',invalid_namespace:'Client invalide.',namespace_not_active:'Le client n’est pas actif.',request_failed:'La requête a échoué.',changeLanguage:'Passer en anglais',changeTheme:'Changer de thème'},en:{overview:'Overview',clients:'MCP clients',targets:'Targets',access:'MCP access',ssh:'SSH capabilities',web:'Web targets',sessions:'Sessions',overviewTitle:'Overview',overviewIntro:'Actual multi-client MCP server status.',statusAction:'View status',appState:'Application',publicSurface:'Public surface',ready:'Ready',authenticatedMcp:'Authenticated MCP',coreTitle:'Operational MCP core',coreText:'Each client owns its namespace and credential. No SSH or Web adapter is installed yet.',clientsIntro:'Manage isolated MCP clients and their credentials.',targetsIntro:'Targets will appear with adapters from later lots.',accessIntro:'Explicit capability publications to namespaces.',createClient:'Create MCP client',showArchived:'Show archived clients',technicalKey:'Technical key',displayName:'Display name',credentialWarning:'The credential grants access to tools published in this namespace.',credentialOnce:'Copy this secret now. It cannot be displayed again.',copied:'I copied the secret',create:'Create',cancel:'Cancel',rotate:'Rotate',revoke:'Revoke',archive:'Archive',active:'Active',revoked:'Revoked',archived:'Archived',emptyClients:'No MCP client.',emptyTargets:'No target: no adapter installed.',emptyAccess:'No published capability.',runtime:'Runtime',listeners:'Listeners',scope:'Scope',singleRuntime:'Single process',listenerValuesMcp:'8099 Ingress · 8098 MCP',scopeValue1:'Lot 1 — MCP core',close:'Close',plannedTitle:'Feature planned for a later lot',plannedText:'This view remains empty until its adapter is installed.',createTitle:'Create MCP client',credentialTitle:'Credential to copy',confirmRevoke:'Permanently revoke this client?',confirmArchive:'Archive this revoked client?',namespace_key_exists:'This key already exists.',invalid_namespace:'Invalid client.',namespace_not_active:'The client is not active.',request_failed:'The request failed.',changeLanguage:'Switch to French',changeTheme:'Change theme'}};
const tr=k=>I[language][k]||k,escapeText=value=>{const node=document.createElement('span');node.textContent=value??'—';return node.innerHTML};function apply(){document.documentElement.lang=language;document.documentElement.dataset.theme=theme;document.querySelectorAll('[data-i18n]').forEach(n=>n.textContent=tr(n.dataset.i18n));document.querySelectorAll('[data-i18n-aria]').forEach(n=>n.ariaLabel=tr(n.dataset.i18nAria));languageButton.textContent=language==='fr'?'EN':'FR';languageButton.ariaLabel=tr('changeLanguage');themeButton.textContent=theme==='dark'?'☀':'☾';themeButton.ariaLabel=tr('changeTheme');renderNamespaces()}
const shell=document.getElementById('drawer-shell'),drawer=document.getElementById('admin-drawer'),languageButton=document.getElementById('language'),themeButton=document.getElementById('theme');let returnFocus=null;function focusables(){return [...drawer.querySelectorAll('button:not([disabled]),input:not([disabled]),a[href],[tabindex]:not([tabindex="-1"])')].filter(n=>!n.closest('[hidden]'))}function clearToken(){document.getElementById('credential-token').textContent=''}function openDrawer(title,panel,trigger){returnFocus=trigger||document.activeElement;document.querySelectorAll('.drawer-panel').forEach(n=>n.hidden=n.id!==panel);document.getElementById('drawer-title').textContent=title;shell.hidden=false;document.body.classList.add('drawer-open');requestAnimationFrame(()=>focusables()[0]?.focus())}function closeDrawer(){if(shell.hidden)return;clearToken();shell.hidden=true;document.body.classList.remove('drawer-open');returnFocus?.focus();returnFocus=null}document.getElementById('drawer-close').onclick=closeDrawer;document.querySelector('.drawer-overlay').onclick=closeDrawer;document.addEventListener('keydown',event=>{if(shell.hidden)return;if(event.key==='Escape'){event.preventDefault();closeDrawer();return}if(event.key!=='Tab')return;const items=focusables(),first=items[0],last=items.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}});
function csrf(){return document.cookie.split('; ').find(v=>v.startsWith('mcb_csrf='))?.split('=')[1]||''}async function api(path,method='GET',body){return fetch(`${base}${path}`,{method,headers:method==='POST'?{'Content-Type':'application/json','X-CSRF-Token':csrf()}:undefined,body:body?JSON.stringify(body):undefined})}async function loadStatus(){const response=await api('/admin/api/v1/status');if(!response.ok)return;const data=await response.json();document.getElementById('namespace-count').textContent=data.namespaces.active}async function loadNamespaces(){const response=await api(`/admin/api/v1/namespaces?include_archived=${document.getElementById('show-archived').checked}`);if(!response.ok)return;namespaces=(await response.json()).namespaces;renderNamespaces()}function renderNamespaces(){const list=document.getElementById('namespace-list');if(!list)return;list.innerHTML=namespaces.length?namespaces.map(n=>`<article class="item-card"><div><h2>${escapeText(n.display_name)}</h2><span class="state ${n.status}">${escapeText(tr(n.status))}</span> · <span class="meta">${escapeText(n.key)} · rev ${n.inventory_revision}</span></div><div class="actions">${n.status==='active'?`<button class="secondary" data-rotate="${n.id}">${tr('rotate')}</button><button class="danger" data-revoke="${n.id}">${tr('revoke')}</button>`:n.status==='revoked'?`<button class="danger" data-archive="${n.id}">${tr('archive')}</button>`:''}</div></article>`).join(''):`<article class="card empty">${tr('emptyClients')}</article>`}async function loadTargets(){const response=await api('/admin/api/v1/targets'),data=await response.json();document.getElementById('target-list').innerHTML=data.targets.length?'':`<article class="card empty">${tr('emptyTargets')}</article>`}async function loadAccess(){const response=await api('/admin/api/v1/publications'),data=await response.json();document.getElementById('publication-list').innerHTML=data.publications.length?data.publications.map(p=>`<article class="item-card"><div><h2>${escapeText(p.published_name)}</h2><span class="meta">${escapeText(p.namespace_key)} → ${escapeText(p.target_key)}</span></div></article>`).join(''):`<article class="card empty">${tr('emptyAccess')}</article>`}
const loaders={overview:loadStatus,clients:loadNamespaces,targets:loadTargets,access:loadAccess};function selectView(){const requested=location.hash.slice(1),allowed=['overview','clients','targets','access','ssh','web','sessions'],view=allowed.includes(requested)?requested:'overview';document.querySelectorAll('.view').forEach(n=>n.classList.toggle('active',n.id===view));document.querySelectorAll('.nav a').forEach(n=>n.classList.toggle('active',n.dataset.view===view));loaders[view]?.()}document.getElementById('status-open').onclick=e=>openDrawer(tr('statusAction'),'status-panel',e.currentTarget);document.getElementById('namespace-create-open').onclick=e=>{document.getElementById('namespace-form').reset();document.getElementById('namespace-message').textContent='';openDrawer(tr('createTitle'),'namespace-form-panel',e.currentTarget)};document.getElementById('namespace-cancel').onclick=closeDrawer;document.getElementById('credential-dismiss').onclick=closeDrawer;document.getElementById('namespace-form').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,response=await api('/admin/api/v1/namespaces','POST',{key:form.key.value,display_name:form.display_name.value});if(!response.ok){document.getElementById('namespace-message').textContent=tr((await response.json()).error.code);return}const data=await response.json();document.getElementById('credential-token').textContent=data.token;openDrawer(tr('credentialTitle'),'credential-panel',returnFocus);await Promise.all([loadNamespaces(),loadStatus()])};document.getElementById('namespace-list').onclick=async event=>{const button=event.target.closest('button');if(!button)return;const id=button.dataset.rotate||button.dataset.revoke||button.dataset.archive;if(button.dataset.rotate){const response=await api('/admin/api/v1/namespaces/rotate','POST',{id});if(response.ok){document.getElementById('credential-token').textContent=(await response.json()).token;openDrawer(tr('credentialTitle'),'credential-panel',button)}}else if(button.dataset.revoke&&confirm(tr('confirmRevoke')))await api('/admin/api/v1/namespaces/revoke','POST',{id});else if(button.dataset.archive&&confirm(tr('confirmArchive')))await api('/admin/api/v1/namespaces/archive','POST',{id});await Promise.all([loadNamespaces(),loadStatus()])};document.getElementById('show-archived').onchange=loadNamespaces;
languageButton.onclick=()=>{language=language==='fr'?'en':'fr';localStorage.setItem('mcb-language',language);apply()};themeButton.onclick=()=>{theme=theme==='dark'?'light':'dark';localStorage.setItem('mcb-theme',theme);apply()};document.querySelectorAll('.nav a').forEach(link=>link.onclick=event=>{event.preventDefault();location.hash=link.dataset.view;selectView()});addEventListener('hashchange',selectView);apply();selectView();
"""
